pm.test("Status code should be 200", () => {
    pm.response.to.have.status(200);

});

pm.test("Verify the response time", ()=>{
pm.expect(pm.response.responseTime).to.be.below(2000);
});

const response = pm.response.json();

pm.test("Carts should be returned as an array", () => {
    pm.expect(response.carts).to.be.an("array");
});

pm.test("Carts should not be empty", () => {
    pm.expect(response.carts.length).to.be.above(0);
});

pm.test("Pagination metadata should be available", () => {
    pm.expect(response.total).to.be.a("number");
    pm.expect(response.limit).to.be.a("number");
    pm.expect(response.skip).to.be.a("number");
});

pm.test("Every cart should contain required fields", () => {
    response.carts.forEach(cart => {
        pm.expect(cart.id).to.be.a("number");
        pm.expect(cart.userId).to.be.a("number");
        pm.expect(cart.products).to.be.an("array");
        pm.expect(cart.total).to.be.a("number");
        pm.expect(cart.totalProducts).to.be.a("number");
        pm.expect(cart.totalQuantity).to.be.a("number");
    });
});

pm.test("Cart IDs should be unique", () => {
    const cartIds = response.carts.map(cart => cart.id);
    pm.expect(new Set(cartIds).size).to.eql(cartIds.length);
});
